const pill=(txt,c)=>`<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-${c}-50 text-${c}-600 border border-${c}-100 whitespace-nowrap"><span class="w-1.5 h-1.5 rounded-full bg-${c}-500"></span>${txt}</span>`;
const delta=(v,up=true)=>`<span class="inline-flex items-center text-[11px] font-bold ${up?'text-emerald-500':'text-red-500'}"><i data-lucide="${up?'arrow-up-right':'arrow-down-right'}" class="w-3.5 h-3.5"></i>${v}</span>`;
const kpi=(icon,label,val,d,sub,c,up=true)=>`<div class="kcol fadein"><div class="kico bg-${c}-50 text-${c}-500"><i data-lucide="${icon}"></i></div><div class="min-w-0"><p class="text-[11px] font-medium text-slate-500 truncate">${label}</p><p class="text-[19px] font-extrabold text-slate-900 leading-tight flex items-center gap-1.5">${val} ${d?delta(d,up):''}</p><p class="text-[10.5px] text-slate-400">${sub}</p></div></div>`;
