const don=(size=110,stroke=13,pct,color='#005AE0',track='#E2E8F0')=>{const r=(size-stroke)/2,c=2*Math.PI*r;return `<div class="relative inline-flex items-center justify-center" style="width:${size}px;height:${size}px"><svg width="${size}" height="${size}" class="-rotate-90"><circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="${track}" stroke-width="${stroke}" fill="none"/><circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="${color}" stroke-width="${stroke}" fill="none" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-pct/100)}"/></svg><div class="absolute inset-0 flex flex-col items-center justify-center"><span class="font-extrabold text-slate-900" style="font-size:${size/5.5}px">${pct}%</span></div></div>`;};
