/* ---------- modal ---------- */
function openModal(title,body,onSave){
  $('#modal-root').innerHTML=`<div class="modal-bg fadein" onclick="if(event.target===this)closeModal()">
    <div class="card w-full max-w-lg p-0 overflow-hidden">
      <div class="flex items-center justify-between px-5 py-4 border-b border-slate-100"><h3 class="font-display font-bold text-[16px]">${title}</h3><button onclick="closeModal()" class="w-8 h-8 rounded-lg hover:bg-slate-100 flex items-center justify-center"><i data-lucide="x" class="w-4 h-4"></i></button></div>
      <div class="px-5 py-4 space-y-3.5">${body}</div>
      <div class="px-5 py-3.5 bg-slate-50 flex justify-end gap-2"><button class="btn-o" onclick="closeModal()">Cancel</button><button class="btn-p" id="modal-save">Save</button></div>
    </div></div>`;
  lucide.createIcons();
  $('#modal-save').onclick=()=>{onSave&&onSave();closeModal();};
}
function closeModal(){$('#modal-root').innerHTML='';}
const fld=(label,inner)=>`<div><label class="block text-[11.5px] font-bold text-slate-500 mb-1.5">${label}</label>${inner}</div>`;

/* ---------- router ---------- */
function go(id){
  state.view=id;
  charts.forEach(c=>{try{c.destroy()}catch(e){}});charts=[];
  renderSidebar();renderTopbar();
  const [title,sub]=TITLES[id];
  $('#app').innerHTML=`<div class="max-w-[1560px] mx-auto fadein">
    <div class="flex items-start justify-between gap-4 flex-wrap mb-4">
      <div><h1 class="font-display font-extrabold text-[26px] text-slate-900 leading-tight">${title}</h1><p class="text-[13px] text-slate-500 mt-0.5">${sub}</p></div>
      <div id="view-actions" class="flex items-center gap-2 flex-none"></div>
    </div>
    <div id="view-body"></div>
  </div>`;
  const __b=VIEWS[id]();const __vb=document.getElementById('view-body');if(__vb){try{__vb.innerHTML=__b;}catch(err){__vb.innerHTML='<div style="padding:2rem;font-family:monospace;color:#b91c1c;font-size:12px"><b>View error:</b> '+(err&&err.message||err)+'</div>';}}
  lucide.createIcons();
  const act=ACTIONS[id];act&&act();
  const vs=VIEW_SCRIPTS[id];vs&&vs();
  $('#app').scrollTop=0;
  bindTabs();
  bindSwitches();
  bindSearch();
  bindDrag();
}
function mkChart(id,cfg){const el=document.getElementById(id);if(!el)return;charts.push(new Chart(el,cfg));}
function bindTabs(){
  $$('[data-tabgroup]').forEach(g=>{
    const key=g.dataset.tabgroup;
    const cur=state.tab[key]||g.dataset.default||g.querySelector('[data-tab]')?.dataset.tab;
    g.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===cur));
    document.querySelectorAll(`[data-pane="${key}"]`).forEach(p=>p.classList.toggle('hidden',p.dataset.paneid!==cur));
  });
}
document.addEventListener('click',e=>{
  const goBtn=e.target.closest('[data-go]');if(goBtn){go(goBtn.dataset.go);return;}
  const tb=e.target.closest('[data-tab]');
  if(tb){const g=tb.closest('[data-tabgroup]');state.tab[g.dataset.tabgroup]=tb.dataset.tab;bindTabs();
    if(g.dataset.tabgroup==='taskfilter'){const f=tb.dataset.tab;$$('#app tbody tr[data-status]').forEach(r=>{r.style.display=(f==='All Tasks'||r.dataset.status===f)?'':'none';});}}
  const pillF=e.target.closest('[data-filter]');
  if(pillF){pillF.closest('[data-filtergroup]').querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active'));pillF.classList.add('active');const f=pillF.dataset.filter;const wrap=pillF.closest('.card, .space-y-3');if(!wrap)return;const tbl=wrap.querySelector('[data-table]')||document.querySelector(`[data-table="${pillF.dataset.filtergroup}"]`);if(!tbl)return;tbl.querySelectorAll('tbody tr').forEach(r=>{const s=r.dataset.status||'';r.style.display=(f==='All'||s===f)?'':'none';});}
  const del=e.target.closest('[data-delrow]');if(del){del.closest('tr').remove();}
  const appr=e.target.closest('[data-approve]');
  if(appr){const tr=appr.closest('tr');tr.dataset.status='Approved';tr.querySelector('[data-statuscell]').innerHTML=pill('Approved','emerald');toast('Leave request approved');}
  const rej=e.target.closest('[data-reject]');
  if(rej){const tr=rej.closest('tr');tr.dataset.status='Rejected';tr.querySelector('[data-statuscell]').innerHTML=pill('Rejected','red');toast('Leave request rejected');}
  const conn=e.target.closest('[data-connect]');
  if(conn){const on=conn.dataset.on==='1';conn.dataset.on=on?'0':'1';conn.textContent=on?'Connect':'Disconnect';conn.className=on?'btn-o !py-1.5 !px-4':'btn-o !py-1.5 !px-4 !bg-emerald-50 !border-emerald-200 !text-emerald-600';toast(on?'Integration disconnected':'Integration connected');}
  const tmpl=e.target.closest('[data-use-tmpl]');if(tmpl){toast('Template added to your automations');}
  const run=e.target.closest('[data-run-auto]');if(run){toast('Automation executed successfully');}
  const mark=e.target.closest('[data-markall]');if(mark){$$('#notif-list .unread-dot').forEach(d=>d.remove());$$('#notif-list .bg-blue-50\/40').forEach(r=>r.classList.remove('bg-blue-50/40'));const nb=document.getElementById('notif-badge');nb&&nb.remove();toast('All notifications marked as read');}
});
function bindSwitches(){$$('.switch').forEach(s=>{if(s.dataset.bound)return;s.dataset.bound='1';s.onclick=()=>{s.classList.toggle('on');toast(s.classList.contains('on')?'Enabled':'Disabled');};});}
function bindSearch(){
  const gs=$('#global-search');
  if(gs&&!gs.dataset.bound){gs.dataset.bound='1';gs.oninput=()=>{const q=gs.value.toLowerCase();$$('#app table tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none');};}
  $$('[data-search]').forEach(inp=>{inp.oninput=()=>{const q=inp.value.toLowerCase();const tbl=document.getElementById(inp.dataset.search);if(!tbl)return;tbl.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none');};});}
let dragEl=null;
function bindDrag(){$$('.taskcard').forEach(c=>{c.ondragstart=()=>{dragEl=c;setTimeout(()=>c.classList.add('dragging'),0);};c.ondragend=()=>c.classList.remove('dragging');});
 $$('.kanban-col').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('ring-2','ring-primary/30');};col.ondragleave=()=>col.classList.remove('ring-2','ring-primary/30');col.ondrop=e=>{e.preventDefault();col.classList.remove('ring-2','ring-primary/30');if(dragEl){col.querySelector('[data-cards]').appendChild(dragEl);const count=col.querySelector('[data-count]');count.textContent='('+col.querySelectorAll('.taskcard').length+')';toast('Task moved to '+col.querySelector('[data-colname]').textContent);}};});}
function toast(msg){const t=document.createElement('div');t.className='fixed bottom-5 right-5 z-[70] bg-navy text-white text-[13px] font-semibold px-4 py-2.5 rounded-xl shadow-lift fadein flex items-center gap-2';t.innerHTML=`<i data-lucide="circle-check-big" class="w-4 h-4 text-emerald-400"></i>${msg}`;document.body.appendChild(t);lucide.createIcons();setTimeout(()=>{t.style.opacity='0';t.style.transition='opacity .3s';setTimeout(()=>t.remove(),300);},2200);}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus();}if(e.key==='Enter'&&e.target.id==='chat-input'){e.preventDefault();sendChat();}});

