ACTIONS.analytics=()=>{
  const spark=(id,c)=>mkChart(id,{type:'line',data:{labels:[...Array(12).keys()],datasets:[{data:Array.from({length:12},()=>20+Math.random()*60),borderColor:c,pointRadius:0,borderWidth:2,tension:.5,fill:true,backgroundColor:c+'18'}]},options:{plugins:{legend:{display:false}},scales:{x:{display:false},y:{display:false}},maintainAspectRatio:false}});
  spark('ch-s1','#3B82F6');spark('ch-s2','#10B981');spark('ch-s3','#8B5CF6');spark('ch-s4','#F59E0B');spark('ch-s5','#3B82F6');spark('ch-s6','#EF4444');
  const days=Array.from({length:14},(_,i)=>`${i+1} Sep`);
  mkChart('ch-antrend',{type:'line',data:{labels:days,datasets:[{label:'Productive',data:days.map(()=>55+Math.random()*30),borderColor:'#10B981',backgroundColor:'rgba(16,185,129,.10)',fill:true,tension:.45,pointRadius:0,borderWidth:2.5},{label:'Neutral',data:days.map(()=>25+Math.random()*12),borderColor:'#3B82F6',backgroundColor:'rgba(59,130,246,.06)',fill:true,tension:.45,pointRadius:0,borderWidth:2},{label:'Distracting',data:days.map(()=>8+Math.random()*10),borderColor:'#EF4444',backgroundColor:'rgba(239,68,68,.05)',fill:true,tension:.45,pointRadius:0,borderWidth:2}]},options:{plugins:{legend:{display:false}},scales:{y:{min:0,max:100,ticks:{callback:v=>v+'%'},grid:{color:'#F1F5F9'}},x:{grid:{display:false},ticks:{maxTicksLimit:5}}}}});
  mkChart('ch-andist',{type:'doughnut',data:{labels:['Productive','Neutral','Distracting','Break'],datasets:[{data:[408,62,32,22],backgroundColor:['#10B981','#2563EB','#F59E0B','#EF4444'],borderWidth:3,borderColor:'#fff'}]},options:{cutout:'72%',plugins:{legend:{display:false}}}});
  const barCfg=(id)=>mkChart(id,{type:'bar',data:{labels:days,datasets:[{data:days.map(()=>100+Math.random()*400),backgroundColor:'#10B981',stack:'a',borderRadius:2},{data:days.map(()=>50+Math.random()*150),backgroundColor:'#3B82F6',stack:'a',borderRadius:2},{data:days.map(()=>20+Math.random()*80),backgroundColor:'#EF4444',stack:'a',borderRadius:2}]},options:{plugins:{legend:{display:false}},scales:{x:{stacked:true,grid:{display:false},ticks:{maxTicksLimit:5}},y:{stacked:true,grid:{color:'#F1F5F9'}}}}});
  barCfg('ch-anshots');barCfg('ch-anurl');
};

