VIEWS.settings=()=>{
  const groups=[['Account',[['settings','General',1],['user','Profile',0],['briefcase','Workspace',0],['palette','Appearance',0],['bell','Notifications',0],['sliders','Preferences',0]]],['Workspace',[['users','Team & Permissions',0],['folder','Projects & Tasks',0],['timer','Time Tracking',0],['clock','Attendance & Leave',0],['wallet','Payroll',0],['file-text','Documents',0],['blocks','Integrations',0],['sparkles','Automation (AI)',0]]],['Security & Privacy',[['shield','Privacy & Security',0],['history','Activity Log',0],['download','Data & Export',0],['trash-2','Danger Zone',0]]]];
  const emailPrefs=[['mail','blue','Product Updates','Get the latest product updates and new features.',1],['clipboard-list','emerald','Task Notifications','Receive emails for task assignments, mentions and updates.',1],['folder','blue','Project Updates','Get notified about project changes and milestones.',1],['calendar','red','Attendance & Leave','Receive notifications for attendance, leave approvals and reminders.',1],['wallet','emerald','Payroll Notifications','Get notified about salary slips and payroll updates.',1],['tag','amber','Marketing & Offers','Receive tips, resources and special offers.',0]];
  return `<div class="grid grid-cols-1 lg:grid-cols-[250px_1fr_290px] gap-4">
    <div class="card p-3 h-fit">${groups.map(([g,items])=>`<p class="px-3 pt-3 pb-1.5 text-[10px] font-extrabold uppercase tracking-wider text-slate-400">${g}</p>${items.map(([ic,l,on])=>`<a class="navlink !text-slate-600 hover:!bg-slate-100 hover:!text-slate-900 ${on?'!bg-blue-50 !text-primary':''}"><i data-lucide="${ic}"></i>${l}</a>`).join('')}`).join('')}</div>
    <div class="card"><div class="px-5 py-4 border-b border-slate-100 flex items-center justify-between"><div><h3 class="font-display font-bold text-[17px]">General Settings</h3><p class="text-[11.5px] text-slate-400">Manage your basic account information and preferences.</p></div><button class="btn-p" onclick="toast('Settings saved')">Save Changes</button></div>
      <div class="px-5 py-5"><p class="text-[13px] font-extrabold text-slate-800 mb-4">Account Information</p>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4">${fld('Full Name',`<input class="inp w-full" value="Rohan Mehta">`)}${fld('Email Address',`<input class="inp w-full" value="rohan.mehta@xspaceweb.com">`)}${fld('Job Title',`<input class="inp w-full" value="Product Designer">`)}${fld('Department',`<select class="inp w-full"><option>Design</option></select>`)}${fld('Phone Number',`<div class="flex"><span class="inp !rounded-r-none border-r-0 flex items-center gap-1.5 font-bold text-slate-600">🇮🇳 +91</span><input class="inp w-full !rounded-l-none" value="98765 43210"></div>`)}${fld('Time Zone',`<select class="inp w-full"><option>(GMT+05:30) Asia/Kolkata</option></select>`)}</div>
      ${fld('About Me',`<textarea class="inp w-full h-20 mt-1">Product Designer at Xspaceweb. Focused on creating user-centered, beautiful and functional digital experiences.</textarea>`)}
      <div class="flex items-center gap-4 mt-4"><div class="relative">${av(13,80)}<span class="absolute bottom-0 right-0 w-6 h-6 rounded-full bg-primary flex items-center justify-center ring-2 ring-white cursor-pointer"><i data-lucide="camera" class="w-3 h-3 text-white"></i></span></div><div><p class="text-[12.5px] font-bold text-slate-800">Profile Photo</p><p class="text-[10.5px] text-slate-400 mb-2">Supported: JPG, PNG (Max 5MB)</p><div class="flex gap-2"><button class="btn-p !py-1.5 !text-[12px]" onclick="toast('Photo upload opened')">Upload New Photo</button><button class="btn-o !py-1.5 !text-[12px]">Remove</button></div></div></div></div>
      <div class="px-5 py-5 border-t border-slate-100"><p class="text-[13px] font-extrabold text-slate-800 mb-1">Email Preferences</p><p class="text-[11.5px] text-slate-400 mb-4">Choose what email notifications you want to receive.</p>
      <div class="space-y-1">${emailPrefs.map(([ic,c,t,s,on])=>`<div class="flex items-center gap-3.5 py-2.5"><span class="w-10 h-10 rounded-xl bg-${c}-50 flex items-center justify-center flex-none"><i data-lucide="${ic}" class="w-4 h-4 text-${c}-500"></i></span><div class="flex-1 min-w-0"><p class="text-[13px] font-bold text-slate-800">${t}</p><p class="text-[11px] text-slate-400">${s}</p></div><span class="switch ${on?'on':''}"></span></div>`).join('')}</div></div>
    </div>
    <div class="space-y-4">
      <div class="card">${cardHead('Workspace Settings')}<div class="px-4 pb-4"><div class="flex items-center gap-3 mb-3"><span class="w-11 h-11 rounded-xl bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center"><i data-lucide="hexagon" class="w-5 h-5 text-white"></i></span><div><p class="text-[13.5px] font-extrabold text-slate-900">Xspaceweb Pvt Ltd</p><p class="text-[10.5px] text-slate-400">Business Plan</p></div></div><button class="btn-o w-full justify-center">Manage Workspace <i data-lucide="external-link" class="w-3.5 h-3.5"></i></button></div></div>
      <div class="card">${cardHead('Preferences')}<div class="px-2 pb-3">${[['globe','Language','English (US)'],['calendar','Date Format','DD MMM YYYY · 29 Sep 2026'],['clock','Time Format','12 Hour (AM/PM)'],['calendar-days','First Day of Week','Monday'],['layout','Default View','List View']].map(([ic,l,v])=>`<div class="flex items-center gap-3 px-2 py-2.5"><i data-lucide="${ic}" class="w-4 h-4 text-slate-400"></i><span class="flex-1 text-[12px] font-bold text-slate-700">${l}</span><button class="btn-o !py-1 !px-2.5 !text-[11px]">${v}<i data-lucide="chevron-down" class="w-3 h-3"></i></button></div>`).join('')}</div></div>
      <div class="card">${cardHead('App Preferences')}<div class="px-2 pb-3">${[['bell-ring','Sound Notifications',1],['monitor','Desktop Notifications',1],['external-link','Auto-open Assignments',0],['calendar','Show Weekend in Calendar',1],['minimize-2','Compact Mode',0],['accessibility','Reduced Motion',0]].map(([ic,l,on])=>`<div class="flex items-center gap-3 px-2 py-2.5"><i data-lucide="${ic}" class="w-4 h-4 text-slate-400"></i><span class="flex-1 text-[12px] font-bold text-slate-700">${l}</span><span class="switch ${on?'on':''}"></span></div>`).join('')}</div></div>
      <div class="card">${cardHead('Account Actions')}<div class="px-2 pb-3">${[['key','Change Password'],['monitor-smartphone','Manage Sessions'],['download','Download My Data']].map(([ic,l])=>`<button class="w-full flex items-center gap-3 px-2 py-2.5 hover:bg-slate-50 rounded-lg text-left"><i data-lucide="${ic}" class="w-4 h-4 text-slate-400"></i><span class="flex-1 text-[12px] font-bold text-slate-700">${l}</span><i data-lucide="chevron-right" class="w-4 h-4 text-slate-300"></i></button>`).join('')}<button class="w-full flex items-center gap-3 px-2 py-2.5 hover:bg-red-50 rounded-lg text-left" onclick="toast('Account deletion requires confirmation')"><i data-lucide="trash-2" class="w-4 h-4 text-red-500"></i><span class="flex-1 text-[12px] font-bold text-red-500">Delete Account</span><i data-lucide="chevron-right" class="w-4 h-4 text-red-300"></i></button></div></div>
    </div>
  </div>`;
};

